NAME = 'ACV: A Conservative Version'
BOOK = 'I John'

CHAPTERS = {
    1: {
        1: 'Kar je bilo od začetka, kar smo slišali, kar smo videli na svoje oči, kar smo gledali in so tipale naše roke, o Besedi življenja',
        2: '(in življenje se je razodelo, in videli smo in pričamo in oznanjujemo vam večno življenje, ki je bilo pri Očetu in se je razodelo nam);',
        3: 'kar smo videli in slišali, oznanjamo vam, da imate tudi vi deleštvo z nami; deleštvo naše pa je z Očetom in Sinom njegovim Jezusom Kristusom.',
        4: 'In to pišemo, da bode veselje vaše popolno.',
        5: 'In to je oznanilo, ki smo ga slišali od njega in ga vam oznanjamo: da je Bog luč, in teme v njem ni nobene.',
        6: 'Ako pravimo, da imamo deleštvo ž njim, pa živimo v temi, lažemo in ne delamo resnice;',
        7: 'če pa živimo v luči, kakor je on v luči, imamo deleštvo med seboj, in kri Jezusa Kristusa, Sina njegovega, nas očiščuje slehernega greha.',
        8: 'Ako pravimo, da nimamo greha, sami sebe slepimo, in resnice ni v nas.',
        9: 'Če pripoznavamo grehe svoje, je zvest in pravičen, da nam odpusti grehe in nas očisti sleherne krivice.',
        10: 'Ako pravimo, da nismo grešili, ga delamo za lažnika, in besede njegove ni v nas.',
    },
    2: {
        1: 'Otročiči moji, to vam pišem, da ne grešite. Ako se pa kdo pregreši, imamo Odvetnika pri Očetu, Jezusa Kristusa pravičnega;',
        2: 'in on je sprava za grehe naše, ne pa samo za naše, ampak tudi za vsega sveta grehe.',
        3: 'In po tem vemo, da smo ga spoznali, ako držimo zapovedi njegove.',
        4: 'Kdor pravi: Spoznal sem ga, a ne drži zapovedi njegovih, je lažnik in v njem ni resnice;',
        5: 'kdor pa izpolnjuje besedo njegovo, v njem je resnično ljubezen Božja dopolnjena. Po tem vemo, da smo v njem.',
        6: 'Kdor pravi, da v njem ostaja, mora tudi tako živeti, kakor je on živel.',
        7: 'Ljubljeni, ne pišem vam nove zapovedi, ampak zapoved staro, ki ste jo imeli od začetka. Stara zapoved je beseda, ki ste jo slišali.',
        8: 'Zopet vam pišemo novo zapoved, kar je resnično v njem in v vas; ker tema gine in prava luč že sveti.',
        9: 'Kdor pravi, da je v luči, pa sovraži brata svojega, je v temi še do sedaj.',
        10: 'Kdor ljubi brata svojega, ostaja v luči in pohujšanja ni v njem.',
        11: 'Kdor pa sovraži brata svojega, je v temi in hodi po temi in ne ve, kam gre, ker tema je oslepila oči njegove.',
        12: 'Pišem vam, otročiči, ker so vam grehi odpuščeni zaradi imena njegovega.',
        13: 'Pišem vam, očetje, ker ste spoznali njega, ki je od začetka. Pišem vam, mladeniči, ker ste premagali Hudobnega. Pisal sem vam, otročiči, ker ste spoznali Očeta.',
        14: 'Pisal sem vam, očetje, ker ste spoznali njega, ki je od začetka. Pisal sem vam, mladeniči, ker ste krepki, in beseda Božja ostaja v vas, in premagali ste Hudobnega.',
        15: 'Ne ljubite sveta, ne tega, kar je na svetu. Če kdo ljubi svet, ni ljubezni Očetove v njem.',
        16: 'Zakaj vse, kar je na svetu: poželenje mesa in poželenje oči in življenja napuh, ni iz Očeta, temuč je iz sveta.',
        17: 'In svet gine in poželenje njegovo; kdor pa dela voljo Božjo, ostane vekomaj.',
        18: 'Otročiči, poslednja ura je, in kakor ste slišali, da se antikrist bliža, so že sedaj vstali mnogi antikristi: odtod spoznavamo, da je poslednja ura.',
        19: 'Izmed nas so izšli, ali niso bili iz nas; kajti ko bi bili iz nas, bi bili ostali z nami: toda odšli so, da se pokažejo, da niso vsi iz nas.',
        20: 'In vi imate maziljenje od Svetega in veste vse.',
        21: 'Nisem vam pisal, ker ne znate resnice, ampak ker jo znate in ker ni nobene laži iz resnice.',
        22: 'Kdo je lažnik, če ne tisti, kdor taji, da Jezus je Kristus? Ta je antikrist, ki taji Očeta in Sina.',
        23: 'Vsak, ki taji Sina, tudi Očeta nima; kdor pripoznava Sina, ima tudi Očeta.',
        24: 'Vi pa – kar ste slišali od začetka, to naj ostane v vas. Če ostane v vas, kar ste slišali od začetka, tudi vi ostanete v Sinu in v Očetu.',
        25: 'In ta je obljuba, ki nam jo je obljubil: večno življenje.',
        26: 'To sem vam pisal za tiste, ki vas slepe.',
        27: 'In za vas: maziljenje, ki ste ga prejeli od njega, ostaja v vas, in treba ni, da bi vas kdo učil; temuč kakor vas maziljenje njegovo uči vsega in je resnično in ni laž, in kakor vas je poučilo, tako ostanite v njem.',
        28: 'In sedaj, otročiči, ostanite v njem, da imamo, če se on prikaže, trdno zaupanje in ne bomo osramočeni pred njim ob prihodu njegovem.',
        29: 'Ako veste, da je pravičen, spoznajte, da je vsak, ki dela pravičnost, iz njega rojen.',
    },
    3: {
        1: 'Poglejte, koliko ljubezen nam je dal Oče, da se imenujemo otroci Božji, in smo tudi. Zato nas svet ne spoznava, ker njega ni spoznal.',
        2: 'Ljubljeni, sedaj smo otroci Božji, a ni se še pokazalo, kaj bodemo. Vemo pa, da bodemo, ko se prikaže, njemu podobni, ker ga bomo videli, kakor je.',
        3: 'In vsak, kdor ima to upanje vanj, očiščuje sebe, kakor je on čist.',
        4: 'Vsak, kdor dela greh, dela tudi protizakonje; in greh je protizakonje.',
        5: 'In veste, da se je on prikazal, da odvzame grehe naše; in greha ni v njem.',
        6: 'Kdorkoli ostaja v njem, ne greši; kdorkoli greši, ga ni videl in ga ni spoznal.',
        7: 'Otročiči, nihče naj vas ne slepi: kdor dela pravičnost, je pravičen, kakor je on pravičen;',
        8: 'kdor dela greh, je iz hudiča, ker hudič greši od začetka. Zato se je prikazal Sin Božji, da razdene dela hudičeva.',
        9: 'Kdorkoli je rojen iz Boga, ne dela greha, ker seme njegovo ostaja v njem, in grešiti ne more, ker je rojen iz Boga.',
        10: 'V tem so očitni otroci Božji in otroci hudičevi: kdorkoli ne dela pravičnosti, ni iz Boga, in kdor ne ljubi brata svojega.',
        11: 'Kajti to je oznanilo, ki ste ga slišali od začetka: naj se ljubimo med seboj;',
        12: 'ne kakor Kajn, ki je bil iz Hudobnega in je ubil brata svojega. In zakaj ga je ubil? Ker so bila hudobna dela njegova, dela brata njegovega pa pravična.',
        13: 'Ne čudite se, bratje moji, če vas svet sovraži.',
        14: 'Mi vemo, da smo prešli iz smrti v življenje, ker ljubimo brate. Kdor ne ljubi, ostaja v smrti.',
        15: 'Vsak, kdor sovraži brata svojega, je ljudomorec; in veste, da noben ljudomorec nima večnega življenja, ki bi prebivalo v njem.',
        16: 'V tem smo spoznali ljubezen, da je on dal življenje za nas; tudi mi moramo dati življenje za brate.',
        17: 'Kdor pa ima premoženje tega sveta in vidi brata svojega, da je v potrebi, a zapre srce svoje pred njim, kako prebiva ljubezen Božja v njem?',
        18: 'Otročiči moji, ne ljubimo z besedo, tudi ne z jezikom, marveč v dejanju in resnici.',
        19: 'In v tem spoznamo, da smo iz resnice, in pred njim bomo pomirili srca svoja,',
        20: 'da, ako nas srce naše obsoja, je Bog večji od srca našega in pozna vse.',
        21: 'Ljubljeni, če nas srce naše ne obsoja, imamo trdno zaupanje do Boga,',
        22: 'in karkoli prosimo, prejmemo od njega, ker držimo zapovedi njegove in delamo, kar je prijetno pred njim.',
        23: 'In ta je zapoved njegova, da verujmo v ime Sina njegovega, Jezusa Kristusa, in se ljubimo med seboj, kakor nam je dal zapoved.',
        24: 'In kdor drži zapovedi njegove, ostaja v Njem in On v njem. In v tem spoznavamo, da ostaja v nas, iz Duha namreč, ki ga nam je dal.',
    },
    4: {
        1: 'Ljubljeni, ne verujte vsakemu duhu, ampak presojajte duhove, ali so iz Boga; ker mnogo lažnivih prorokov je prišlo na svet.',
        2: 'V tem spoznate Duha Božjega: vsak duh, ki pripoznava Jezusa Kristusa, da je prišel v mesu, je iz Boga;',
        3: '§ in vsak duh, ki ne pripoznava Jezusa, da je prišel v mesu, ni iz Boga, in ta je duh antikristov, o katerem ste slišali, da se bliža, in sedaj je že na svetu.',
        4: 'Vi ste iz Boga, otročiči, in premagali ste jih; ker večji je on, ki je v vas, nego on, ki je v svetu.',
        5: 'Oni so iz sveta; zato govore, kar je iz sveta, in svet jih posluša.',
        6: 'Mi smo iz Boga; kdor poznava Boga, posluša nas, kdor ni iz Boga, nas ne posluša. Iz tega spoznavamo duha resnice in duha zmote.',
        7: 'Ljubljeni, ljubimo se med seboj; kajti ljubezen je iz Boga, in vsak, kdor ljubi, je rojen iz Boga in spoznava Boga.',
        8: 'Kdor ne ljubi, ni spoznal Boga, ker Bog je ljubezen.',
        9: 'V tem se je razodela ljubezen Božja v nas, da je Bog poslal Sina svojega edinorojenega na svet, da bi živeli po njem.',
        10: 'V tem je ljubezen, ne da smo mi ljubili Boga, temuč da je on ljubil nas in poslal Sina svojega v spravo za grehe naše.',
        11: 'Ljubljeni, če nas je Bog tako ljubil, dolžni smo tudi mi ljubiti se med seboj.',
        12: 'Boga ni nihče nikdar videl; če se ljubimo med seboj, ostaja Bog v nas in ljubezen njegova je dopolnjena v nas.',
        13: 'V tem spoznavamo, da ostajamo v njem in on v nas, ker nam je dal od Duha svojega.',
        14: 'In mi smo videli in pričujemo, da je Oče poslal Sina kot Zveličarja sveta.',
        15: 'Kdor pripoznava, da je Jezus Sin Božji, v njem ostaja Bog in on v Bogu.',
        16: 'In mi smo spoznali in verovali ljubezen, ki jo ima Bog do nas. Bog je ljubezen, in kdor ostaja v ljubezni, ostaja v Bogu in Bog v njem.',
        17: 'V tem se je dopolnila ljubezen pri nas, da imamo trdno zaupanje ob dnevi sodbe; ker kakor je on, smo tudi mi na tem svetu.',
        18: 'Strahu ni v ljubezni, temuč popolna ljubezen izganja strah, ker strah povzroča trpljenje; kdor pa se boji, ni popoln v ljubezni.',
        19: 'Mi ga ljubimo, ker nas je on prvi ljubil.',
        20: 'Ako kdo pravi: Boga ljubim, pa sovraži brata svojega, je lažnik; kdor namreč ne ljubi brata svojega, katerega vidi, kako more ljubiti Boga, ki ga ne vidi?',
        21: 'In to zapoved imamo od njega, da kdor ljubi Boga, naj ljubi tudi brata svojega.',
    },
    5: {
        1: 'Vsak, kdor veruje, da Jezus je Kristus, je rojen iz Boga; in vsak, kdor ljubi njega, ki ga je rodil, ljubi tudi tega, ki je rojen iz njega.',
        2: 'V tem spoznavamo, da ljubimo otroke Božje, ako ljubimo Boga in izpolnjujemo zapovedi njegove.',
        3: 'Kajti to je ljubezen Božja, da držimo zapovedi njegove; in zapovedi njegove niso težke.',
        4: 'Ker vse, kar je rojeno iz Boga, premaga svet; in to je zmaga, ki je premagala svet: vera naša.',
        5: 'Kdo je, ki premaga svet, če ne tisti, ki veruje, da je Jezus Sin Božji?',
        6: 'Ta je, ki je prišel po vodi in krvi, Jezus Kristus; ne z vodo samo, ampak z vodo in s krvjo.',
        7: 'In Duh je, ki pričuje, ker Duh je resnica.',
        8: 'Kajti trije so, ki pričajo: Duh in voda in kri, in ti trije so eno v svojem pričanju.',
        9: 'Če sprejemamo pričevanje ljudi, pričevanje Božje je večje: kajti to je pričevanje Božje, da je pričal za Sina svojega.',
        10: 'Kdor veruje v Sina Božjega, ima pričevanje v sebi; kdor ne veruje Bogu, ga je naredil za lažnika, ker ni veroval v pričevanje, ki ga je Bog pričal za Sina svojega.',
        11: 'In to je pričevanje: da nam je Bog dal večno življenje, in to življenje je v Sinu njegovem.',
        12: 'Kdor ima Sina ima življenje; kdor nima Sina Božjega, nima življenja.',
        13: 'To sem vam pisal, da veste, da imate večno življenje, kateri verujete v ime Sina Božjega.',
        14: 'In to je trdno zaupanje, ki ga imamo do njega, da nas sliši, ako kaj prosimo po volji njegovi;',
        15: 'in če vemo, da nas sliši, česarkoli prosimo, vemo, da nam je izpolnjeno, česar smo ga prosili.',
        16: 'Ako kdo vidi brata svojega, da greši, a ne greha za smrt, bo prosil, in dá mu Bog življenje, njim namreč, ki ne greše za smrt. Je greh za smrt; ne za tega, pravim, naj prosi.',
        17: 'Sleherna krivica je greh; a je greh, ki ni za smrt.',
        18: 'Vemo, da kdorkoli je rojen iz Boga, ne greši; temuč kdor je bil rojen iz Boga, varuje sebe in Hudobni se ga ne dotakne.',
        19: 'Vemo, da smo iz Boga, in ves svet leži v Hudobnem.',
        20: 'Vemo pa, da je Sin Božji prišel in nam dal razum, da spoznamo Resničnega; in smo v Resničnem, v Sinu njegovem Jezusu Kristusu. Ta je resnični Bog in življenje večno.',
        21: 'Otročiči, varujte se malikov!',
    },
}
